/* N2 grammar source adapted from jkindrix/japanese-language-data (CC BY-SA 4.0). Chinese brief glosses are project additions. See grammar-bulk-SOURCES.md. All source entries draft/unreviewed. */
window.JLPT_GRAMMAR_SOURCE_N2=[["ni-atatte-occasion","V plain non-past / noun + にあたって / にあたり","值此……之际；在……时（正式）","on the occasion of / at the time of (formal)","V plain non-past + にあたって / にあたり; noun + にあたって / にあたり.",[["新年にあたって、ご挨拶申し上げます。","On the occasion of the new year, I offer my greetings."],["出発にあたり、準備を整えた。","In preparation for departure, I made ready."],["卒業にあたって、先生に感謝を伝えた。","On the occasion of graduation, I conveyed my thanks to my teacher."]],"draft"],["ni-sakidatte-prior","V plain / noun + に先立って / に先立ち","在……之前；事先","prior to / in advance of","V plain non-past + に先立って / に先立ち; noun + に先立って / に先立ち.",[["会議に先立って、資料を配布した。","Prior to the meeting, I distributed the materials."],["発表に先立ち、リハーサルを行った。","In advance of the announcement, we held a rehearsal."],["出発に先立って、パスポートを確認した。","Prior to departure, I checked my passport."]],"draft"],["wo-kikkake-ni","Noun / V plain + をきっかけに(して)","以……为契机；因为……而开始","triggered by / with X as the impetus","Noun + をきっかけに(して); V plain / V-た + の + をきっかけに(して).",[["日本旅行をきっかけに、日本語を勉強し始めた。","A trip to Japan triggered my starting to study Japanese."],["その本を読んだのをきっかけに、考え方が変わった。","Reading that book triggered a change in my way of thinking."],["病気をきっかけに、健康に気をつけるようになった。","My illness triggered me to start caring about my health."]],"draft"],["wo-keiki-ni","Noun + を契機に / を契機として","借……机会；以……为转折点","taking X as the opportunity / prompted by","Noun + を契機に / を契機として.",[["事故を契機に、安全対策を強化した。","Prompted by the accident, safety measures were strengthened."],["留学を契機として、彼の人生は大きく変わった。","Taking studying abroad as the turning point, his life changed greatly."],["退職を契機に、趣味に時間を使うようになった。","Prompted by retirement, he began spending time on hobbies."]],"draft"],["ni-tsuki-due-to","Noun + につき","因为……；每……（单位）","due to / because of / per","Noun + につき (for both senses, disambiguated by context).",[["本日は定休日につき、閉店いたします。","As today is our regular closing day, we are closed."],["お一人につき、1000円です。","It's 1000 yen per person."],["改装中につき、通路が狭くなっています。","Due to renovations, the passageway has been narrowed."]],"draft"],["yue-ni-because","Plain form + (が)ゆえに / 故に","因为……；所以……（书面）","because / therefore (literary)","V plain / i-adj + (が)ゆえに; na-adj + (な / である) + (が)ゆえに; noun + の + ゆえに.",[["我思う、ゆえに我あり。","I think, therefore I am."],["若さゆえに、失敗することもある。","Because of youth, one sometimes fails."],["彼は正直であるがゆえに、損をすることも多い。","Precisely because he is honest, he often loses out."]],"draft"],["koto-kara-from-fact","Plain form + ことから","从……的事实判断；鉴于","from the fact that / based on the fact","V plain / i-adj + ことから; na-adj + な / である + ことから; noun + である + ことから.",[["桜の木が多いことから、この町は'桜町'と呼ばれている。","From the fact that it has many cherry trees, this town is called 'Sakura Town'."],["足跡が残っていることから、犯人は2人だと分かった。","From the fact that footprints remained, we knew there were two culprits."],["彼の顔が赤いことから、お酒を飲んだことが分かる。","From his red face, you can tell he's been drinking."]],"draft"],["amari-too-much","V plain / i-adj / na-adj な / noun の + あまり","由于过度……；过分……而","out of excess / from too much","V plain + あまり; i-adj + さ + の + あまり; na-adj + な + あまり / noun (emotion) + の + あまり.",[["驚きのあまり、言葉を失った。","Out of sheer surprise, I was lost for words."],["悲しみのあまり、泣き出した。","Out of too much sadness, I burst into tears."],["働きすぎたあまり、体を壊した。","From working too much, I ruined my health."]],"draft"],["ba-koso-precisely-because","V ば-form + こそ","正因为……才……（强调）","precisely because / it is only because","V ば-form + こそ; i-adj 〜ければ + こそ; na-adj / noun + であれば + こそ.",[["君を愛していればこそ、こう言うのだ。","It's precisely because I love you that I say this."],["健康であればこそ、仕事ができる。","It is only because one is healthy that one can work."],["努力すればこそ、成功が得られる。","Only by making effort can success be obtained."]],"draft"],["kara-koso-precisely-because","Plain form + からこそ","恰恰因为……才……","precisely because / it is exactly because","V plain / i-adj + からこそ; na-adj / noun + だ + からこそ.",[["大切な友達だからこそ、厳しいことも言う。","It's precisely because you're a dear friend that I say harsh things too."],["難しいからこそ、挑戦する価値がある。","Precisely because it's difficult, it's worth the challenge."],["努力したからこそ、成功した。","It's precisely because I worked hard that I succeeded."]],"draft"],["ni-tomonatte-accompany","Noun / V plain + に伴って / に伴い","伴随……；随着……发展","accompanying / along with / as X progresses","Noun + に伴って / に伴い; V plain + の + に伴って.",[["少子化に伴って、学校が減っている。","Along with the declining birthrate, the number of schools is decreasing."],["経済成長に伴い、都市化が進んだ。","Along with economic growth, urbanization progressed."],["技術の進歩に伴って、生活が便利になった。","With the progress of technology, life has become more convenient."]],"draft"],["ni-oujite-depending","Noun + に応じて","根据……；按照……作出回应","depending on / in response to / in accordance with","Noun + に応じて (adverbial); noun + に応じた + noun (attributive).",[["能力に応じて、仕事が与えられる。","Work is given according to ability."],["状況に応じて、対応を変える必要がある。","We need to change our response depending on the situation."],["需要に応じて、生産量を調整する。","We adjust production volume in response to demand."]],"draft"],["ni-kotaete-response","Noun + にこたえて","响应……；满足期待或要求","in response to / responding to (expectations, requests)","Noun + にこたえて; attributive 〜にこたえた + noun.",[["観客の声援にこたえて、選手たちはベストを尽くした。","Responding to the audience's cheers, the athletes gave their best."],["期待にこたえて、彼は見事に優勝した。","Meeting expectations, he brilliantly won the championship."],["お客様の要望にこたえて、新商品を開発した。","Responding to customer requests, we developed a new product."]],"draft"],["ni-kakawarazu-regardless","Plain form / noun + にかかわらず","不论……；无论……","regardless of / irrespective of","Noun + にかかわらず; plain form (pair of opposites) + にかかわらず (e.g., 行く行かないにかかわらず).",[["年齢にかかわらず、誰でも参加できます。","Regardless of age, anyone can participate."],["天気にかかわらず、試合は行われる。","Regardless of the weather, the match will be held."],["経験のあるなしにかかわらず、挑戦してみてください。","Regardless of experience, please try."]],"draft"],["ni-mo-kakawarazu-despite","Plain form + にもかかわらず","尽管……；虽然……","despite / in spite of / even though","V plain / i-adj + にもかかわらず; na-adj + である + にもかかわらず; noun + にもかかわらず.",[["悪天候にもかかわらず、試合は行われた。","Despite the bad weather, the match was held."],["努力したにもかかわらず、結果が出なかった。","Despite making an effort, no result came."],["忙しいにもかかわらず、手伝ってくれた。","Despite being busy, he helped me."]],"draft"],["wo-towazu-regardless","Noun + を問わず","不问……；无论……","regardless of / without regard to","Noun + を問わず. Often with pairs: 男女を問わず, 年齢を問わず, 経験の有無を問わず.",[["男女を問わず、応募できます。","Regardless of gender, you can apply."],["国籍を問わず、みんな歓迎します。","Regardless of nationality, all are welcome."],["経験の有無を問わず、参加可能です。","Regardless of prior experience, participation is possible."]],"draft"],["wa-tomokaku","Noun + はともかく(として)","暂且不论……；先把……放一边","setting X aside / putting X aside / regardless of","Noun + はともかく / はともかくとして.",[["値段はともかく、品質を確認しましょう。","Setting price aside, let's check the quality."],["結果はともかく、最善を尽くすことが大事だ。","Regardless of the result, doing one's best is what matters."],["冗談はともかくとして、話を戻しましょう。","Joking aside, let's get back to the topic."]],"draft"],["wa-sate-oki","Noun + はさておき","暂且不谈……（正式）","setting X aside (formal)","Noun + はさておき.",[["冗談はさておき、真面目な話をしましょう。","Setting jokes aside, let's have a serious conversation."],["それはさておき、次の議題に移ります。","Setting that aside, let's move to the next topic."],["詳細はさておき、概要を説明します。","Setting details aside, I'll explain the outline."]],"draft"],["ni-kagitte-only","Noun + に限って","偏偏……时；唯独……","of all (things/people/times) / precisely when","Noun + に限って + (typically negative or surprising main clause).",[["急いでいる時に限って、電車が遅れる。","Of all times, the train gets delayed when I'm in a hurry."],["うちの子に限って、嘘はつかない。","Not my child — he would never lie."],["今日に限って、傘を忘れた。","Of all days, today I forgot my umbrella."]],"draft"],["ni-kagirazu-not-only","Noun + に限らず","不仅限于……；不仅……","not limited to / not only X (but also)","Noun + に限らず.",[["日本に限らず、世界中でこの問題がある。","Not only in Japan — this problem exists around the world."],["子供に限らず、大人もこの本を楽しめる。","Not limited to children, adults can also enjoy this book."],["女性に限らず、男性も料理を楽しむ時代だ。","This is an era when not only women but men also enjoy cooking."]],"draft"],["zu-ni-wa-irarenai","V negative stem + ずにはいられない","情不自禁……；忍不住……","can't help doing / can't stop oneself from","V ない-stem + ずにはいられない. Irregular: する → せずにはいられない.",[["あまりにもおかしくて、笑わずにはいられなかった。","It was so funny, I couldn't help but laugh."],["彼の優しさに、感動せずにはいられない。","I can't help being moved by his kindness."],["この本を読むと、考えずにはいられない。","Reading this book, I can't help but think."]],"draft"],["nai-dewa-irarenai","V ない-form + ではいられない","忍不住……（较口语）","can't help doing / can't stop oneself from (casual variant)","V ない-form + ではいられない.",[["面白くて笑わないではいられなかった。","It was funny — I couldn't help but laugh."],["彼女の話を聞いて泣かないではいられなかった。","Hearing her story, I couldn't help but cry."],["真実を知って、怒らないではいられない。","Knowing the truth, I can't help being angry."]],"draft"],["te-wa-irarenai","V-て form + (は)いられない","不能一直……；没时间再……","can't afford to be (doing X) / can't stay (in state X)","V-て + はいられない (polite: いられません). Casual contraction: 〜ちゃいられない.",[["こうしてはいられない。早く行こう。","I can't just stay like this. Let's hurry."],["試験が近いので、遊んではいられない。","The exam is near, so I can't afford to play around."],["彼の危険を思うと、寝てはいられない。","Thinking of his danger, I can't just sleep."]],"draft"],["ni-shiro-ni-seyo","Plain form + にしろ / にせよ","即使……；不论……（正式）","even if / whether or not (formal)","Plain-form clause / noun + にしろ; plain-form clause / noun + にせよ. Paired: X にしろ Y にしろ.",[["行くにしろ行かないにしろ、早く決めてください。","Whether you go or not, please decide quickly."],["失敗するにせよ、挑戦するべきだ。","Even if you fail, you should try."],["どちらにしろ、結論は変わらない。","Either way, the conclusion won't change."]],"draft"],["toshite-mo-even-as","Plain form + としても","即使……；假设……","even if / even assuming / even as","V plain / i-adj / na-adj / noun + としても.",[["失敗したとしても、経験にはなる。","Even if I fail, it will become experience."],["行くとしても、明日の朝だ。","Even if I go, it will be tomorrow morning."],["嘘だとしても、信じたい。","Even if it's a lie, I want to believe it."]],"draft"],["you-to-regardless","Verb volitional + と / ようと","无论……怎样……","regardless of / no matter (what / who / how)","V volitional (〜よう / 〜おう) + と. Often with interrogatives: 誰が〜ようと, 何を〜ようと.",[["誰が何と言おうと、私は諦めない。","No matter what anyone says, I won't give up."],["雨が降ろうと、試合は行われる。","No matter if it rains, the match will be held."],["何があろうと、私はあなたの味方だ。","No matter what happens, I'm on your side."]],"draft"],["you-to-mai-to","V volitional + と + V dict-form/ます-stem + まい(と)","无论做不做……都……","whether or not (one does) X","V volitional + と + V ます-stem / dict-form + まい(と). Example: 行こうと行くまいと, 食べようと食べまいと.",[["行こうと行くまいと、あなたの自由だ。","Whether you go or not, it's up to you."],["彼が来ようと来まいと、会議は始める。","Whether he comes or not, we'll start the meeting."],["雨が降ろうと降るまいと、出発する。","Rain or no rain, we're leaving."]],"draft"],["mai-not-likely","Verb dict / ます-stem + まい","不打算……；大概不会……","will not / probably not / intention not to","Godan / Ichidan V dict + まい (or 〜ます stem + まい for ichidan, varied). Irregular: する → すまい / しまい; くる → くまい / こまい.",[["もう二度と彼とは会うまい。","I'll never see him again."],["そんな簡単には負けるまい。","I won't lose so easily."],["彼は来まい。","He probably won't come."]],"draft"],["nuku-fully-do","Verb ます-stem + 抜く","坚持做到底；彻底……","do X to the very end / thoroughly","V ます-stem + 抜く (conjugates as godan: 抜きます, 抜いた, 抜いて).",[["最後まで走り抜いた。","I ran through to the very end."],["困難を乗り越えて、生き抜いた。","Overcoming hardship, he survived through."],["じっくり考え抜いて決めた。","I decided after thinking it through thoroughly."]],"draft"],["kane-nai-might","Verb ます-stem + かねない","可能会……（负面结果）","might / could (something bad)","V ます-stem + かねない (polite: かねません).",[["そんなに無理すると、病気になりかねない。","If you push yourself that hard, you might get sick."],["彼ならやりかねない。","Knowing him, he might do it."],["油断すると、大きな失敗をしかねない。","If you're careless, you might make a big mistake."]],"draft"],["kane-ru-hard-to","Verb ます-stem + かねる","难以……；不能轻易……","cannot (quite) / hard to / difficult to","V ます-stem + かねる (polite: かねます).",[["その質問にはお答えしかねます。","I cannot quite answer that question."],["ご要望には応じかねます。","I'm afraid we cannot meet your request."],["賛成しかねる意見だ。","It's an opinion I can't quite agree with."]],"draft"],["dzurai-hard-emotional","Verb ます-stem + づらい","做……很难受；难以……","hard to do (emotionally / uncomfortably)","V ます-stem + づらい. Functions as an i-adjective and conjugates regularly.",[["それは少し言いづらい話だ。","That's a bit of an awkward topic to bring up."],["彼に質問しづらい。","It's hard to ask him questions."],["この靴は歩きづらい。","These shoes are hard to walk in."]],"draft"],["gatai-difficult","Verb ます-stem + がたい","难以……（正式）","hard / difficult to (formal)","V ます-stem + がたい. Functions as an i-adjective.",[["それは信じがたい話だ。","That's a hard-to-believe story."],["許しがたい行為だ。","It is an unforgivable act."],["想像しがたい光景だった。","It was a hard-to-imagine scene."]],"draft"],["beku-in-order-to","Verb dict-form + べく","为了……（书面）","in order to / for the purpose of (literary)","V dict-form + べく. Irregular: する → すべく (formal) or するべく.",[["夢を実現すべく、毎日努力している。","In order to realize my dream, I work hard every day."],["健康を取り戻すべく、運動を始めた。","In order to regain my health, I started exercising."],["事件を解決すべく、警察は調査を続けた。","In order to solve the case, the police continued their investigation."]],"draft"],["wa-mochiron","Noun + はもちろん(のこと)","……自不必说；当然……","not to mention / of course / needless to say","Noun + はもちろん / はもちろんのこと.",[["日本人はもちろん、外国人にも人気だ。","It's popular not only with Japanese people but also with foreigners."],["子供はもちろんのこと、大人も楽しめる。","Needless to say children, but adults can also enjoy it."],["漢字はもちろん、ひらがなも書けない。","Not to mention kanji, he can't even write hiragana."]],"draft"],["wo-tsuujite-through","Noun + を通じて / を通して","通过……；贯穿……","through / via / throughout (all of)","Noun + を通じて; noun + を通して. Attributive form: を通じての + noun.",[["友達を通じて彼に紹介された。","I was introduced to him through a friend."],["一年を通じて観光客が多い。","There are many tourists throughout the year."],["この経験を通して、多くのことを学んだ。","Through this experience, I learned many things."]],"draft"],["ni-wataru-span","Noun + にわたって / にわたり / にわたる","跨越……；涉及……范围","over / spanning / across (a period or extent)","Noun (time / area / domain) + にわたって / にわたり; noun + にわたる + noun (attributive).",[["10年にわたって研究を続けた。","I continued the research over 10 years."],["長年にわたる努力が実を結んだ。","Many years of effort bore fruit."],["広範囲にわたり雨が降った。","It rained over a wide area."]],"draft"],["wo-chuushin-ni-centered","Noun + を中心に(して)","以……为中心；主要围绕……","centered on / focusing on / mainly","Noun + を中心に / を中心にして; attributive 〜を中心とした + noun.",[["環境問題を中心に話し合った。","We discussed, focusing on environmental issues."],["この地域は農業を中心に発展してきた。","This region has developed centered on agriculture."],["若者を中心に、この音楽が流行している。","Centered on young people, this music is popular."]],"draft"],["wo-komete","Noun + を込めて","倾注……（感情）","with (feeling) / putting (feeling) into","Noun (emotion) + を込めて.",[["愛を込めて手紙を書いた。","I wrote the letter with love."],["感謝を込めてプレゼントを贈る。","I give a present with gratitude."],["心を込めて歌った。","I sang with all my heart."]],"draft"],["ni-shite-wa","Noun + にしては","就……而言；与预期不同","for (a) / considering X (surprising)","Noun + にしては.",[["初めてにしては、上手に弾けた。","For a first try, I played it well."],["子供にしては、よく知っている。","For a child, he knows a lot."],["新人にしては、仕事ができる。","For a newcomer, he's capable at his work."]],"draft"],["ni-shite","Noun + にして","在……时／达到……程度（强调）","at (the point of) / being (X), (emphatic)","Noun + にして. Typically with age, position, or identity nouns.",[["彼は80歳にして、今も元気だ。","At 80 years old, he is still energetic."],["今にして思えば、あれが最後のチャンスだった。","Now that I think about it, that was my last chance."],["彼は医者にして作家でもある。","He is a doctor and also a writer."]],"draft"],["sue-ni-after","V-た form / noun + の + 末(に)","经过长时间……之后","after (a long process) / at the end of","V-た + 末(に); noun + の + 末(に). Attributive: 〜末の + noun.",[["長い間悩んだ末、留学することにした。","After agonizing for a long time, I decided to study abroad."],["議論の末、結論が出た。","After much discussion, a conclusion was reached."],["苦労の末、成功をつかんだ。","After many hardships, he finally grasped success."]],"draft"],["dake-no-koto-wa-aru","Plain form + だけのことはある","不愧是……；果然名不虚传","(it's) as expected from / lives up to","V plain / i-adj + だけのことはある; na-adj + な + だけのことはある; noun + (である) + だけのことはある.",[["長年練習しただけのことはある。演奏が素晴らしい。","The years of practice have paid off. The performance is wonderful."],["高いだけのことはある。本当に美味しい。","It lives up to its high price — really delicious."],["プロだけのことはあるね。","He really lives up to being a pro."]],"draft"],["made-mo-nai","Verb dict-form + までもない","连……都没必要；不值得……","no need to even / not worth (doing)","V dict-form + までもない. Fixed phrase: 言うまでもない / 言うまでもなく.",[["言うまでもなく、日本の首都は東京だ。","Needless to say, Japan's capital is Tokyo."],["そんなことで病院に行くまでもない。","There's no need to go so far as to visit a hospital for that."],["わざわざ行くまでもないよ。","No need to go out of your way."]],"draft"],["to-iu-mono-da","Plain form + というものだ","所谓……就是……","that's what X is / that's (the nature of) X","Plain-form clause + というものだ; noun + というものだ.",[["困っている人を助けるのが友情というものだ。","Helping a friend in need — that's what friendship is."],["それが現実というものだ。","That's what reality is."],["苦労して手に入れたものほど大切にする、というものだ。","The harder something is to obtain, the more you treasure it — that's how it is."]],"draft"],["to-iu-mono-dewa-nai","Plain form + というものではない","不能单纯地说……；并非……","it's not simply (a matter of) / it's not that","Plain-form clause + というものではない / というものでもない.",[["お金があれば幸せになれるというものではない。","It's not simply that having money makes you happy."],["勉強すれば必ず成功するというものではない。","It's not just that studying guarantees success."],["謝れば済むというものではない。","It's not just a matter of apologizing to make it right."]],"draft"],["mono-dakara","Plain form + ものだから / もので","因为……嘛（解释或辩解）","because / it's because (excusing / justifying)","V plain / i-adj + ものだから; na-adj + な + ものだから; noun + な + ものだから.",[["急いでいたものだから、挨拶もせずに帰ってしまった。","Because I was in a hurry, I left without even saying goodbye."],["最近忙しいもので、連絡が遅くなりました。","I've been busy lately, so my reply was delayed."],["小さい子供がいるものですから、夜は外出できません。","Since I have small children, I can't go out at night."]],"draft"],["yara-yara","Noun + やら + noun + やら","……之类的种种事情","things like X and Y (disordered / overwhelming)","Noun + やら + noun + やら; verb plain / i-adj + やら + verb / i-adj + やら.",[["宿題やら掃除やらで忙しい。","I'm busy with homework and cleaning and whatnot."],["雨やら風やらで、外に出られなかった。","What with the rain and the wind, I couldn't go out."],["嬉しいやら恥ずかしいやら、複雑な気持ちだった。","I felt happy and embarrassed and all mixed up."]],"draft"],["kara-shite","Noun + からして","单从……看就……；以……为例","judging from / starting with (as a representative example)","Noun + からして.",[["あの人は話し方からして失礼だ。","That person is rude — just from the way they speak, you can tell."],["見た目からして、すごく美味しそうだ。","Just from the look, it seems very delicious."],["名前からしてユニークだ。","Starting with the name, it's unique."]],"draft"],["kara-suru-to","Noun + からすると / からすれば","从……的立场看","from X's standpoint / judging from","Noun + からすると / からすれば.",[["専門家からすると、この問題は簡単だ。","From an expert's standpoint, this problem is easy."],["彼の話し方からすれば、怒っているようだ。","Judging from how he's speaking, he seems angry."],["外国人からすると、日本語の漢字は難しい。","From a foreigner's standpoint, Japanese kanji are difficult."]],"draft"],["kara-ni-wa","Plain form + からには","既然……就……（责任、决心）","now that / since (with strong obligation)","V plain / i-adj + からには; na-adj / noun + である + からには.",[["約束したからには、必ず守ります。","Now that I've promised, I will definitely keep it."],["日本に来たからには、日本語をマスターしたい。","Now that I've come to Japan, I want to master Japanese."],["やるからには、最後までやる。","If I'm going to do it, I'll see it through."]],"draft"],["no-minarazu","Plain form + のみならず","不仅……而且……（书面）","not only X but also Y (literary)","V plain / i-adj + のみならず; na-adj + である + のみならず; noun + のみならず.",[["彼は頭がいいのみならず、性格もいい。","Not only is he smart, but he also has a good personality."],["この問題は日本のみならず、世界中で議論されている。","This issue is debated not only in Japan but around the world."],["学生のみならず、大人にも役立つ本だ。","This book is useful not only for students but also for adults."]],"draft"],["to-wa-ie","Plain form + とはいえ","虽说……；话虽如此","although / that said / even so","V plain / i-adj + とはいえ; na-adj / noun (+ だ) + とはいえ.",[["もう春とはいえ、まだ寒い。","Although it's already spring, it's still cold."],["忙しいとはいえ、家族の時間は大切だ。","Busy as I am, family time is important."],["子供とはいえ、責任感がある。","Although he's a child, he has a sense of responsibility."]],"draft"],["to-wa-iu-mono-no","Plain form + とはいうものの","虽然这么说……但是……","that said / although one says","V plain / i-adj + とはいうものの; na-adj / noun + (だ) + とはいうものの.",[["春だとはいうものの、今朝は雪が降った。","Although we say it's spring, snow fell this morning."],["お金が大事だとはいうものの、それがすべてではない。","Although we say money is important, it's not everything."],["便利だとはいうものの、問題もある。","Although it's called convenient, it also has problems."]],"draft"],["ni-shite-mireba","Noun + にしてみれば / にしてみたら","站在……的立场来看","from X's perspective / from X's point of view","Noun + にしてみれば / にしてみたら.",[["子供にしてみれば、当然の反応だ。","From a child's perspective, it's a natural reaction."],["私にしてみれば、そんなのは大した問題じゃない。","From my perspective, that's not a big deal."],["外国人にしてみたら、難しいかもしれない。","From a foreigner's perspective, it may be difficult."]],"draft"],["kara-to-itte","Plain form + からといって","不能只因为……就……","just because / even though (one says)","Plain-form clause + からといって (+ negative or hedged main clause).",[["お金があるからといって、幸せとは限らない。","Just because you have money doesn't necessarily mean you're happy."],["若いからといって、何でも許されるわけではない。","Just because you're young doesn't mean everything is forgiven."],["高いからといって、必ずしもいいとは限らない。","Just because it's expensive doesn't mean it's necessarily good."]],"draft"],["koto-dakara","Noun + の + ことだから","考虑到……的特点；既然是……","knowing X / given that it's X","Noun (person) + の + ことだから.",[["時間に厳しい田中さんのことだから、きっと時間通りに来るだろう。","Knowing Mr. Tanaka, who is strict about time, he'll surely come on time."],["真面目な彼のことだから、ちゃんと宿題をしているはずだ。","Knowing he's so diligent, he must be doing his homework properly."],["忘れっぽい私のことだから、また鍵を忘れるかもしれない。","Knowing forgetful me, I might forget my keys again."]],"draft"],["te-kara-to-iu-mono","V-て form + からというもの","自从……以来一直……","ever since / since that time","V-て + からというもの + (main clause describing ongoing state).",[["日本に来てからというもの、毎日が楽しい。","Ever since I came to Japan, every day has been enjoyable."],["その本を読んでからというもの、考え方が大きく変わった。","Ever since I read that book, my way of thinking has changed greatly."],["子供が生まれてからというもの、自由な時間が全くない。","Ever since my child was born, I have had no free time at all."]],"draft"],["tsutsu-aru","Verb ます-stem + つつある","正在逐渐……；变化进行中","in the process of / gradually becoming","V ます-stem + つつある.",[["地球温暖化が進みつつある。","Global warming is progressing."],["日本の人口は減りつつある。","Japan's population is gradually decreasing."],["状況は改善しつつある。","The situation is gradually improving."]],"draft"],["dake-mashi-da","Plain form + だけましだ","至少……总比没有好","at least X (is better than nothing) / could be worse","V plain / i-adj + だけましだ; na-adj + な + だけましだ; noun + (な) + だけましだ.",[["雨だけど、雪じゃないだけましだ。","It's raining, but at least it's not snowing."],["給料は低いが、仕事があるだけましだ。","My salary is low, but at least I have a job."],["風邪は辛いが、熱がないだけましだ。","Having a cold is rough, but at least I don't have a fever."]],"draft"],["ya-inaya","Verb dict-form + や否や","刚一……就……（书面）","as soon as / the moment that (literary)","V dict-form + や否や.",[["彼は家に着くや否や、ベッドに倒れ込んだ。","As soon as he got home, he collapsed into bed."],["ドアを開けるや否や、猫が飛び出した。","The moment I opened the door, the cat jumped out."],["始業のベルが鳴るや否や、生徒たちは席についた。","The moment the opening bell rang, the students took their seats."]],"draft"],["ka-nai-ka-no-uchi-ni","V dict + か + V ない + かのうちに","刚……就……；还没……就……","no sooner (had X) than Y / barely had one Xed when Y","V dict + か + same V ない-form + かのうちに + main clause.",[["家に着くか着かないかのうちに、雨が降り出した。","No sooner had I arrived home than it started to rain."],["ベルが鳴るか鳴らないかのうちに、生徒たちは教室を出た。","No sooner had the bell rung than the students left the classroom."],["目を閉じるか閉じないかのうちに、眠ってしまった。","No sooner had I closed my eyes than I fell asleep."]],"draft"],["sobakara","Verb plain / V-た form + そばから","每次刚……就又……（反复）","as soon as / immediately after (with repeated undoing)","V plain / V-た + そばから.",[["教えたそばから忘れてしまう。","He forgets as soon as I teach him."],["片付けたそばから、子供が散らかす。","As soon as I clean up, the children make a mess."],["注意するそばから、また同じ間違いをする。","As soon as I warn him, he makes the same mistake again."]],"draft"],["ja-arumai-shi","Noun / plain form + じゃあるまいし","又不是……；并非……","it's not as if / since it's not like","Noun + じゃあるまいし / ではあるまいし; plain form + わけじゃあるまいし.",[["子供じゃあるまいし、そんなことで泣かないで。","You're not a child — don't cry over that."],["初めてじゃあるまいし、もう慣れたでしょう。","It's not your first time — surely you're used to it by now."],["プロじゃあるまいし、そんなに完璧を求めるな。","You're not a pro, so don't demand such perfection."]],"draft"],["to-bakari-ni","Plain form / phrase + とばかりに","仿佛在说……；一副……样子","as if to say / seemingly saying","Quoted phrase / plain-form clause + とばかりに.",[["彼は「もう限界だ」とばかりに、ため息をついた。","He sighed as if to say 'I've had enough'."],["子供は「早く行こう」とばかりに、私の手を引っ張った。","The child pulled my hand as if to say 'let's go quickly'."],["彼女は「知らない」とばかりに、顔を背けた。","She turned her face away as if to say 'I don't know'."]],"draft"],["to-areba","Noun / plain form + とあれば","如果是为了……；既然是……","if it's (a case of) / if it's for","Noun + とあれば; plain-form clause + とあれば.",[["あなたのためとあれば、何でもする。","If it's for you, I'll do anything."],["緊急とあれば、すぐ駆けつけます。","If it's an emergency, I'll rush over immediately."],["必要とあれば、お手伝いします。","If it's necessary, I'll help."]],"draft"],["nai-made-mo","V ない-form + までも","即便称不上……至少……","even if not quite X / not necessarily X, but at least","V ない + までも.",[["完璧とは言わないまでも、かなりよくできている。","I wouldn't call it perfect, but it's done quite well."],["毎日とは言わないまでも、週に一度は運動したい。","Not every day, but at least once a week I'd like to exercise."],["直接会わないまでも、電話くらいはしてほしい。","Even if you don't meet in person, I'd at least like you to call."]],"draft"],["no-moto-de","Noun + のもとで / のもとに","在……指导／条件下","under (the guidance / condition / auspices of)","Noun + のもとで (adverbial) / のもとに (literary variant).",[["有名な先生のもとで、ピアノを学んだ。","I studied piano under a famous teacher."],["青空のもとで、ピクニックを楽しんだ。","We enjoyed a picnic under the blue sky."],["厳しい条件のもとに、契約が結ばれた。","The contract was concluded under strict conditions."]],"draft"],["sou-ni-nai","Verb ます-stem + そうにない / そうもない","看起来不像……；没有……迹象","doesn't look like / there's no sign of","V ます-stem + そうにない (neutral) / そうもない (slightly more emphatic). Irregular: いい → よさそうにない (rare).",[["雨が降りそうにない。","It doesn't look like it's going to rain."],["今日は終わりそうもない。","It doesn't look like I'll finish today."],["彼は来そうにないね。","He doesn't look like he's coming."]],"draft"],["zu-jimai","V negative stem + ずじまい","结果一直没有……；未能……","ended up not (doing) / didn't manage to","V ない-stem + ずじまい (or + で + なる, etc.). Irregular: する → せずじまい.",[["忙しくて、彼に会えずじまいだった。","I was so busy I didn't manage to see him."],["言いたいことも言えずじまいだった。","I ended up not saying what I wanted to say."],["結局、本を読まずじまいになった。","In the end, I didn't manage to read the book."]],"draft"],["ta-tokoro-de","Verb-た form + ところで","即使……也……（无济于事）","even if / no matter if (futile effort)","V-た + ところで + (usually negative main clause).",[["今さら謝ったところで、許してもらえない。","Even if you apologize now, you won't be forgiven."],["走ったところで、もう間に合わない。","Even if I run, I won't make it in time."],["言ったところで、どうにもならない。","Even if I say it, nothing will change."]],"draft"],["nani-shiro","なにしろ (sentence-initial)","毕竟……；因为……","after all / you see / it's because","なにしろ [sentence]. Often followed by 〜から / のだ / んだ.",[["なにしろ、彼は経験が豊富だ。","After all, he has a wealth of experience."],["なにしろ初めてのことなので、不安だ。","You see, it's my first time, so I'm nervous."],["なにしろ忙しかったから、連絡できなかった。","The thing is, I was so busy I couldn't contact you."]],"draft"],["nani-se","なにせ (sentence-initial)","总之……；事情是这样的……","after all / the thing is","なにせ [sentence]. Often followed by から / のだ / だから.",[["なにせ、久しぶりだからよく覚えていない。","After all, it's been a long time, so I don't remember well."],["なにせ忙しいので、時間がない。","The thing is, I'm busy, so I don't have time."],["なにせ初めてなので、ドキドキします。","Since it's my first time, I'm nervous."]],"draft"],["ageku-ni-end-up","V-た form / noun + の + あげく(に)","折腾半天最终……（负面）","in the end / after all / finally (negative result)","V-た + あげく(に); noun + の + あげく(に). Attributive: 〜あげくの + noun.",[["散々悩んだあげく、結局何も決められなかった。","After endlessly worrying, in the end I couldn't decide anything."],["ケンカのあげく、二人は別れてしまった。","After the fight, the two ended up breaking up."],["長い議論のあげく、結論は出なかった。","After a long discussion, no conclusion was reached."]],"draft"],["hanmen-on-other-hand","Plain form + 反面","另一方面；与之相反","on the other hand / while (one side)","V plain / i-adj + 反面; na-adj + な / である + 反面; noun + である + 反面.",[["この仕事は給料がいい反面、責任が重い。","This job has good pay, but on the other hand, heavy responsibility."],["便利な反面、危険もある。","It's convenient, but on the other hand, there's also danger."],["彼は優しい反面、厳しい面もある。","He is kind, yet also has a strict side."]],"draft"],["kara-miru-to","Noun + から見ると / から見れば / から見て","从……观点来看","from the viewpoint of / from X's perspective","Noun + から見ると / から見れば / から見て.",[["外国人から見ると、日本は安全な国だ。","From a foreigner's perspective, Japan is a safe country."],["子供から見れば、両親は絶対的な存在だ。","From a child's perspective, parents are absolute figures."],["データから見て、この商品は人気がある。","Judging from the data, this product is popular."]],"draft"],["to-iu-koto-da","Plain form + ということだ","听说……；意思是……","I hear that / it means that","Plain-form clause + ということだ / とのことだ (more formal hearsay variant).",[["ニュースによると、明日は雨が降るということだ。","According to the news, it's going to rain tomorrow."],["つまり、彼は来ないということだ。","In other words, it means he isn't coming."],["田中さんはもう日本を発ったということです。","It seems Mr. Tanaka has already left Japan."]],"draft"],["kekka-result","V-た form / noun + の + 結果","结果……；经过……之后","as a result of / after","V-た + 結果; noun + の + 結果. Attributive: 〜結果の + noun.",[["調査した結果、新しい事実が分かった。","As a result of our investigation, new facts came to light."],["議論の結果、結論が出た。","As a result of the discussion, a conclusion was reached."],["努力の結果、成功を収めた。","As a result of my effort, I achieved success."]],"draft"],["shidai-de","Noun + 次第で / 次第では","取决于……；视……而定","depending on / according to","Noun + 次第で / 次第では.",[["天気次第で、予定を変更する。","I'll change the plan depending on the weather."],["結果次第では、再検討も必要だ。","Depending on the result, reconsideration may be necessary."],["君の努力次第で、未来は変わる。","Depending on your effort, the future will change."]],"draft"],["ni-itaru","Noun + に至る","达到……；发展至……","reach / arrive at / come to","Noun + に至る; attributive に至る + noun.",[["議論の結果、合意に至った。","As a result of the discussion, we reached an agreement."],["この結論に至った経緯を説明します。","I will explain how we came to this conclusion."],["事故に至る原因を調査した。","We investigated the causes leading to the accident."]],"draft"],["ni-itaru-made","Noun + に至るまで","甚至达到……；一直到……","even to / all the way to / as far as","Noun + に至るまで.",[["子供からお年寄りに至るまで、みんな楽しめる。","Everyone, from children all the way to the elderly, can enjoy it."],["細部に至るまで、丁寧に作られている。","It's carefully made all the way down to the details."],["彼は服装から話し方に至るまで、完璧だ。","He's perfect, from his clothing all the way to his way of speaking."]],"draft"],["sai-ni","V plain / noun + の + 際(に)","在……的时候（正式）","on the occasion of / at the time of (formal)","V plain + 際(に); noun + の + 際(に). The に is optional.",[["非常の際は、このボタンを押してください。","In case of emergency, press this button."],["ご利用の際には、注意事項をお読みください。","Upon use, please read the precautions."],["出張の際に、京都に寄った。","During my business trip, I stopped by Kyoto."]],"draft"],["wo-hete","Noun + を経て","经过……；通过……过程","after going through / via / through (a process)","Noun + を経て.",[["長年の研究を経て、ついに発見した。","After many years of research, we finally discovered it."],["多くの困難を経て、ここまで来た。","After going through many hardships, I've come this far."],["彼は大学を経て、会社員になった。","After going through university, he became a company employee."]],"draft"],["wo-fumaete","Noun + を踏まえて","依据……；考虑到……","based on / taking into account / in view of","Noun + を踏まえて.",[["現状を踏まえて、対策を立てた。","Based on the current situation, we formulated a countermeasure."],["過去の失敗を踏まえて、計画を見直した。","Taking past failures into account, we revised the plan."],["データを踏まえた結論を出した。","We came to a conclusion grounded in the data."]],"draft"],["wo-yoso-ni","Noun + をよそに","对……置之不理；无视……","ignoring / in disregard of","Noun + をよそに.",[["親の心配をよそに、彼は一人で旅に出た。","Disregarding his parents' worries, he set off alone on a trip."],["周囲の反対をよそに、彼らは結婚した。","Ignoring the opposition around them, they got married."],["人々の批判をよそに、彼は自分の道を進んだ。","Disregarding people's criticism, he went his own way."]],"draft"],["doori-just-as","Noun + 通り / どおり","正如……；按照……","just as / according to / exactly like","Noun + どおり; V plain + とおり.",[["予定どおりに出発した。","We departed just as planned."],["先生の指示どおりに行動してください。","Please act according to the teacher's instructions."],["思ったとおりの結果だった。","The result was just as I thought."]],"draft"],["ikan-depending","Noun + いかん / いかんで / いかんによって","取决于……（正式）","depending on / according to (formal)","Noun + いかん / いかんで / いかんによって / いかんにかかわらず.",[["結果いかんで、今後の方針を決める。","Depending on the result, we'll decide future policy."],["成績のいかんにかかわらず、全員合格できる。","Regardless of grades, everyone can pass."],["君の頑張りいかんによって、採用が決まる。","Depending on your effort, the hiring will be decided."]],"draft"],["uru-possible","Verb ます-stem + 得る / 得ない","有可能……；能够……","is possible / can / is capable of","V ます-stem + 得る (うる / える). Negative: 〜得ない (えない).",[["このようなことは起こり得る。","Something like this is possible to happen."],["それはあり得ない。","That's impossible."],["考え得る限りの対策を取った。","We took every conceivable countermeasure."]],"draft"],["to-atte","Plain form + とあって","因为……这一特殊情况","because it's / given that it's (special situation)","Plain-form clause / noun + とあって.",[["休日とあって、公園は大勢の人で賑わった。","Being a holiday, the park was crowded with many people."],["有名な歌手が来るとあって、会場は満員だった。","Because a famous singer was coming, the venue was full."],["初めての海外旅行とあって、とても緊張している。","Being my first trip abroad, I'm very nervous."]],"draft"],["te-kara-denai-to","V-て form + からでないと / からでなければ","不先……就不能……","not until after / unless you first","V-て + からでないと / からでなければ + negative main clause.",[["説明を聞いてからでないと、始められない。","We can't start until after hearing the explanation."],["手を洗ってからでなければ、食事できません。","You cannot eat until you first wash your hands."],["よく考えてからでないと、決められない。","I can't decide until after I think it over well."]],"draft"],["nai-koto-niwa","V ない-form + ことには","如果不……就无法……","unless / without doing (X, can't do Y)","V ない + ことには + negative / inability main clause.",[["実際に見てみないことには、分からない。","Unless I actually see it, I can't tell."],["お金がないことには、生活ができない。","Without money, I can't live."],["試してみないことには、効果は分からない。","Unless you try it, you won't know the effect."]],"draft"],["to-mieru","Plain form + とみえる","看来……；似乎……","it seems that / appears to","Plain-form clause + とみえる (polite: とみえます).",[["彼は忙しいとみえる。","It seems he is busy."],["雨が降っていたとみえて、道がぬれている。","It seems it was raining — the road is wet."],["彼は納得したとみえる。","He seems to have been convinced."]],"draft"],["to-sureba","Plain form + とすれば / とすると / としたら","假如……；如果……","supposing / assuming / if it's the case that","Plain-form clause / noun (+ だ) + とすれば / とすると / としたら.",[["もし雨が降るとすれば、どうしますか。","Supposing it rains, what will you do?"],["彼の話が本当だとすると、大変なことだ。","If his story is true, that's a big problem."],["宝くじが当たったとしたら、何を買いますか。","Supposing you won the lottery, what would you buy?"]],"draft"],["wa-oroka","Noun + はおろか","更不用说……；别说……","let alone / not to mention","Noun + はおろか + (typically negative / more extreme statement).",[["漢字はおろか、ひらがなも書けない。","Not to mention kanji, I can't even write hiragana."],["海外旅行はおろか、国内旅行さえしたことがない。","Let alone overseas trips, I haven't even done domestic travel."],["会話はおろか、挨拶もできない。","Not to mention conversation, I can't even greet people."]],"draft"],["ni-suginai","Noun / plain form + にすぎない","只不过……；仅仅……","is nothing more than / merely","Noun + にすぎない; plain-form clause + にすぎない.",[["それは単なる言い訳にすぎない。","That's nothing more than a mere excuse."],["これはほんの一例にすぎない。","This is merely one example."],["彼の話は推測にすぎない。","His story is nothing more than speculation."]],"draft"],["tatte-even-casual","Plain form + (っ)たって","即使……（口语）","even if (casual)","V-た (short form) + って; i-adj stem + くたって; na-adj / noun + だって.",[["言ったって、聞いてくれないよ。","Even if I told him, he wouldn't listen."],["高くたって、買いたい。","Even if it's expensive, I want to buy it."],["どんなに頑張ったって、無理なものは無理だよ。","No matter how hard you try, what's impossible is impossible."]],"draft"],["koto-tote","Plain form / noun + の + こととて","由于……（正式解释）","since / because (formal, explanatory)","V plain / i-adj + こととて; na-adj + な + こととて; noun + の + こととて.",[["初めてのこととて、不手際をお許しください。","Since it's my first time, please forgive any mishandling."],["急なこととて、ご迷惑をおかけしました。","Since it was sudden, I caused you inconvenience."],["若いこととて、無礼をお許しください。","Since he is young, please forgive his rudeness."]],"draft"],["atte-no-thanks-to","Noun + あっての + noun","多亏有……才得以……","only possible thanks to / made possible by","Noun + あっての + noun.",[["お客様あっての商売です。","It's a business that exists only thanks to our customers."],["健康あっての人生だ。","Life is only meaningful with health."],["家族あっての幸せだ。","Happiness is only possible thanks to family."]],"draft"],["ni-terashite","Noun + に照らして","根据……衡量；参照……","in light of / in accordance with","Noun (rule / standard) + に照らして.",[["法律に照らして、この行為は違法だ。","In light of the law, this act is illegal."],["経験に照らして判断する。","I'll judge based on my experience."],["事実に照らして考えてみよう。","Let's think about it in light of the facts."]],"draft"],["kagiri-da-emotional","i-adj / na-adj + 限りだ","……极了；非常……（情感）","feel extremely / the limit of (an emotion)","i-adj + 限りだ; na-adj + な + 限りだ.",[["あなたにお会いできて、嬉しい限りです。","I'm extremely happy to meet you."],["彼が来ないのは、寂しい限りだ。","Him not coming is extremely lonely."],["力不足で、情けない限りです。","Falling short of expectations, I feel utterly ashamed."]],"draft"],["kiwamari-nai","na-adj root + 極まりない / 極まる","极其……；……到极点","extremely / in the extreme","na-adj root + 極まる or 極まりない. Both forms mean 'extremely'.",[["彼の態度は失礼極まりない。","His attitude is extremely rude."],["危険極まる状況だった。","It was an extremely dangerous situation."],["残念極まりない結果だ。","It's an extremely regrettable result."]],"draft"],["hodo-no-mono-dewa-nai","Plain form + ほどのことではない / ほどのものではない","没那么严重；不值得……","not worth that much / not such a big deal","V plain / noun + ほどのことではない; noun + ほどのものではない.",[["心配するほどのことではないよ。","It's not worth worrying about."],["それは謝るほどのことではない。","That's not worth apologizing over."],["まあまあの出来だが、自慢するほどのものではない。","It turned out okay, but it's nothing to brag about."]],"draft"],["zutomo-even-without","V negative stem + ずとも","即便不……也……","even without / even if not","V ない-stem + ずとも. Irregular: する → せずとも.",[["言わずとも分かるだろう。","You should understand without me saying it."],["急がずとも、間に合うだろう。","Even without hurrying, we'll make it in time."],["心配せずとも大丈夫だ。","You needn't worry — it's fine."]],"draft"],["dano-dano","X だの Y だの","……之类（带抱怨、轻蔑）","things like X and Y (complaining / disparaging listing)","Noun / plain-form predicate + だの + noun / plain-form predicate + だの.",[["忙しいだの疲れただの、言い訳ばかりだ。","'Busy' this, 'tired' that — nothing but excuses."],["嫌いだの苦手だのと、文句ばかり言う。","'Hate this', 'not good at that' — he just complains."],["暑いだの寒いだの、いつも不満ばかりだ。","'Too hot', 'too cold' — always complaining about something."]],"draft"],["to-miru-see-as","Plain form + とみる","认为……；判断为……","see as / regard as / judge to be","Plain-form clause / noun + とみる.",[["警察は事故の原因を不注意とみている。","The police see the cause of the accident as negligence."],["専門家は今後の見通しを楽観的とみる。","Experts see the future outlook as optimistic."],["彼は成功するとみて間違いない。","He's sure to succeed — there's no doubt about it."]],"draft"],["you-de-seemingly","Plain form + ようで / ようでいて","看似……其实……","seemingly X, but actually / looks X but","V plain / i-adj + ようで / ようでいて; na-adj + な / である + ようで; noun + の / である + ようで.",[["彼は強いようでいて、実は優しい。","He seems strong, but is actually gentle."],["簡単なようで、実は難しい。","It seems simple, but it's actually difficult."],["忙しいようで、暇そうだ。","He seems busy, but actually he looks free."]],"draft"],["sae-sureba-if-only","Verb ます-stem / noun + さえ + conditional","只要……就……","if only / as long as (the minimal condition is met)","V ます-stem + さえすれば; noun + さえ + plain-form verb conditional (e.g., さえあれば, さえなければ).",[["お金さえあれば、何でも買える。","As long as you have money, you can buy anything."],["勉強さえすれば、合格できる。","If only you study, you can pass."],["時間さえあれば、手伝えるのに。","If only I had time, I could help."]],"draft"],["datte-casual-because","だって (sentence-initial, casual)","因为……／可是……（口语辩解）","because / but / however (casual defensive)","だって [sentence].",[["だって、嫌なんだもん。","But I just don't want to!"],["だって、本当のことだよ。","Because it's the truth."],["だって、知らなかったんだから仕方ない。","But I didn't know — it can't be helped."]],"draft"],["to-itte-without-particular","Plain form + といって / これといって","没有特别……；没什么值得……","nothing in particular / nothing notable","これといって + negative (no particular); noun + といって + negative.",[["これといって問題はありません。","There's nothing in particular that's a problem."],["これといって趣味はない。","I don't have any particular hobbies."],["これといって理由はない。","There's no particular reason."]],"draft"],["you-nara-if-looks","Plain form + ようなら(ば)","如果看起来……的话","if it looks like / if it appears","V plain / i-adj + ようなら; na-adj + な + ようなら; noun + の + ようなら.",[["雨が降るようなら、中止しましょう。","If it looks like it'll rain, let's cancel."],["難しいようなら、手伝います。","If it looks difficult, I'll help."],["間に合わないようなら、連絡してください。","If it looks like you won't make it in time, please contact me."]],"draft"],["you-dewa-if-its","Plain form + ようでは","若如此……；照这样下去","if it's like that / at this rate","V plain / i-adj + ようでは; na-adj + な + ようでは; noun + の + ようでは.",[["そんなに怠けるようでは、合格できないよ。","If you're lazy like that, you won't pass."],["約束を破るようでは、信頼できない。","If you break promises like that, I can't trust you."],["こんなミスをするようでは、プロとは言えない。","If you make mistakes like this, you can't call yourself a pro."]],"draft"],["zukume-nothing-but","Noun + ずくめ","清一色……；尽是……","nothing but / entirely / all X","Noun + ずくめ. Limited to certain nouns — mostly colors, qualities, notable outcomes.",[["彼女はいつも黒ずくめの服を着ている。","She is always dressed all in black."],["今日はいいことずくめの一日だった。","Today was a day full of nothing but good things."],["異例ずくめの出来事だった。","It was an event full of unprecedented things."]],"draft"],["mamire-smeared","Noun + まみれ","满是……；沾满……（不佳）","smeared / covered with (often messy or unpleasant)","Noun (usually liquid / powder / unpleasant substance) + まみれ.",[["子供は泥まみれになって遊んでいた。","The child was playing, covered in mud."],["彼のシャツは血まみれだった。","His shirt was covered with blood."],["長い間使っていなかった本はほこりまみれだった。","The long-unused book was covered with dust."]],"draft"],["buru-pretend","Noun / i-adj stem / na-adj root + ぶる","装作……；摆出……架子","pretend to be / put on airs of","Noun / i-adj stem / na-adj root + ぶる (conjugates as godan u-verb).",[["彼は学者ぶっているけれど、実はよく知らない。","He's pretending to be a scholar, but actually he doesn't know much."],["いい子ぶるのはやめなさい。","Stop pretending to be a good kid."],["彼女はいつも上品ぶっている。","She's always putting on refined airs."]],"draft"],["meku-have-look","Noun + めく","带有……感觉；显得……","have a look / hint / feel of","Noun + めく (conjugates as godan u-verb).",[["最近、ようやく春めいてきた。","Recently, it's finally starting to feel like spring."],["謎めいた話を聞いた。","I heard a mysterious story."],["その言葉には皮肉めいた響きがあった。","The words had an ironic ring to them."]],"draft"],["mono-ga-aru","Plain form + ものがある","有一种……的感觉","there is something (about it) / is impressively","V plain / i-adj + ものがある; na-adj + な + ものがある.",[["彼の演奏には感動的なものがある。","There's something moving about his performance."],["この町には独特なものがある。","There's something unique about this town."],["彼の考え方には深いものがある。","There's something deep about his way of thinking."]],"draft"],["to-iu-ka","X というか Y","或者说……；应该说……","or rather / I mean","X というか Y (Y provides an alternative or more accurate description).",[["彼は優しいというか、おとなしいタイプだ。","He's kind, or rather, a quiet type."],["疲れたというか、眠いというか、とにかく休みたい。","Tired, or sleepy, or something — anyway I want to rest."],["好きというか、興味がある。","I don't 'like' it exactly — I'm interested."]],"draft"],["to-mo-naku","Verb dict-form + ともなく / ともなしに","不知不觉地……；无意识地……","unintentionally / without consciously","V dict-form + ともなく / ともなしに.",[["見るともなく窓の外を眺めていた。","I was gazing out the window without really looking."],["聞くともなしに、彼らの会話を聞いていた。","I was listening to their conversation without meaning to."],["待つともなく待っていたら、彼が現れた。","I wasn't really waiting, but he showed up."]],"draft"],["kara-iu-to","Noun + からいうと / からいえば / からいって","从……方面来说","from X's viewpoint / speaking from X","Noun + からいうと / からいえば / からいって.",[["結果からいうと、大成功だった。","From the results, it was a big success."],["経験からいえば、早めに行動した方がいい。","From experience, it's better to act early."],["値段からいって、このレストランは高級だ。","Judging from the price, this restaurant is upscale."]],"draft"],["naku-mo-nai","V ない-form + くもない / もない","倒也不是不……；也不是不能……","not that I don't / it's not that X isn't","V ない-form + (く)もない; i-adj 〜くない + くもない; na-adj + でなくもない.",[["行きたくなくもないが、時間がない。","It's not that I don't want to go, but I don't have time."],["彼の意見もわからなくもない。","I can sort of see his point."],["そう考えられなくもない。","It's not that I can't think of it that way."]],"draft"],["ni-kakatte-iru","Noun + にかかっている","取决于……；关键在于……","depends on / hinges on","Noun + にかかっている (polite: にかかっています).",[["成功はあなたの努力にかかっている。","Success depends on your effort."],["このプロジェクトの運命は彼の判断にかかっている。","The fate of this project hinges on his judgment."],["すべては明日の天気にかかっている。","Everything depends on tomorrow's weather."]],"draft"],["to-iu-no-wa","Noun / plain form + というのは","所谓……就是……；原因是……","what is called / the fact is / the reason is","Noun + というのは; plain-form clause + というのは.",[["友情というのは、お金で買えないものだ。","Friendship is something you can't buy with money."],["遅れたというのは、電車が止まったからだ。","The reason I was late is that the train stopped."],["学ぶというのは、楽しいことだ。","Learning is a joyful thing."]],"draft"],["hate-ni-after","V-た form / noun + の + 果てに","经过很长过程最终……","at the very end of / after (extensive process)","V-た + 果てに; noun + の + 果てに.",[["長年の努力の果てに、夢を実現した。","After years of effort, he finally realized his dream."],["彼は放浪の果てに、ここに辿り着いた。","After long wandering, he arrived here."],["激しい議論の果てに、ようやく合意に達した。","After fierce debate, we finally reached an agreement."]],"draft"],["sobireru-miss-chance","Verb ます-stem + そびれる","错过做……的机会","miss the chance to / fail to","V ます-stem + そびれる (conjugates as ichidan: そびれます, そびれた).",[["言いそびれたことがある。","There's something I missed the chance to say."],["忙しくて、昼ごはんを食べそびれた。","I was so busy I missed my chance to eat lunch."],["聞きそびれてしまった。","I missed the chance to ask."]],"draft"],["yashinai-emphatic","V ます-stem + やしない","绝不……（口语强调）","(emphatic) not at all / definitely not (casual)","V ます-stem + やしない (most common) or V ない-form + やしない.",[["そんなこと、分かりやしない。","There's no way I'd understand that."],["誰も聞きやしないよ。","Nobody's going to listen."],["彼は気にしやしない。","He doesn't care at all."]],"draft"],["makuru-extensively","Verb ます-stem + まくる","一个劲儿地……；不停……","do X a lot / do X extensively / keep doing","V ます-stem + まくる (conjugates as godan u-verb).",[["試験前に勉強しまくった。","I studied a ton before the exam."],["休みの日は寝まくる。","On my days off, I sleep a lot."],["彼は一日中ゲームをやりまくっている。","He's playing video games all day long."]],"draft"],["to-iu-koto-wa","Plain form + ということは","也就是说……；由此可见……","what it means is / so (it follows that)","Plain-form clause + ということは.",[["彼が来ないということは、忙しいのだろう。","His not coming means he's probably busy."],["この結果が出たということは、実験が成功したということだ。","The fact that we got this result means the experiment was a success."],["明日休みだということは、今夜遅くまで起きていられる。","Tomorrow being a holiday means I can stay up late tonight."]],"draft"],["ka-to-iu-to","Plain form + かというと / かといえば","至于是否……；要说……","as for whether / if you ask whether","Plain-form clause + かというと / かといえば. Common fixed phrase: どちらかというと.",[["好きかというと、そうでもない。","As for whether I like it — not really."],["どちらかといえば、犬より猫の方が好きだ。","If anything, I prefer cats to dogs."],["上手かというと、まだまだだ。","As for whether I'm good at it — not yet, by far."]],"draft"],["mono-to-shite","Noun + ものとして","作为……；视为……","as / regarded as / assuming that","Noun + ものとして; plain-form clause + ものとして.",[["本件は合意したものとして扱います。","We will treat this matter as agreed upon."],["この規則は絶対的なものとして守ってください。","Please follow this rule as something absolute."],["そう決まったものとして、次に進みましょう。","Assuming that's decided, let's move on."]],"draft"],["te-mo-ii-kurai","V-て form + もいいくらい","到了几乎可以……的程度","enough to / to the extent that (you could)","V-て + もいいくらい.",[["泣いてもいいくらい感動した。","I was moved enough that I could have cried."],["叫んでもいいくらい嬉しかった。","I was so happy I could have shouted."],["踊ってもいいくらいの気分だ。","I feel so good I could dance."]],"draft"],["ato-wa-rest","Noun / plain form + あとは","剩下的只是……；接下来……","the rest is / all that's left is","Noun + あとは; V plain + あとは.",[["準備はできた。あとは出発するだけだ。","Preparations are done. All that's left is to depart."],["書類を作成した。あとは上司の承認を待つだけだ。","I prepared the documents. The rest is just waiting for the boss's approval."],["材料は全部そろった。あとは料理するだけだ。","All the ingredients are ready. The rest is just cooking."]],"draft"],["dake-nara","Noun / V plain + だけなら","如果只是……的话","if only / if it's just X","Noun + だけなら; V plain + だけなら.",[["見るだけなら、いいですよ。","If it's just looking, it's fine."],["それだけなら、私でもできる。","If it's just that, even I can do it."],["ちょっとだけなら、貸してあげる。","If it's just a little, I'll lend it to you."]],"draft"],["nai-nomi-narazu","V ない + のみならず","不仅没有……反而……","not only does not / not just failing to","V ない / noun + でない + のみならず.",[["彼は謝らないのみならず、逆に怒り出した。","Not only did he not apologize, but he even got angry."],["問題は解決しないのみならず、悪化している。","Not only is the problem not solved, but it's getting worse."],["返事をくれないのみならず、連絡も取れない。","Not only does he not reply, I can't even contact him."]],"draft"],["tsutsu-while","Verb ます-stem + つつ","一边……一边……；虽然……却（正式）","while doing / although (formal)","V ます-stem + つつ (simultaneous); V ます-stem + つつも (concessive 'although doing').",[["音楽を聞きつつ、本を読んだ。","I read a book while listening to music."],["悪いと知りつつも、やってしまった。","Although I knew it was wrong, I went ahead and did it."],["景色を楽しみつつ、歩いた。","I walked while enjoying the scenery."]],"draft"],["ni-shitagatte","Noun + にしたがって / V plain + にしたがって","遵照……；随着……变化","in accordance with / as (X progresses)","Noun + にしたがって (accordance); V plain + にしたがって (parallel change).",[["ルールにしたがって、行動してください。","Please act in accordance with the rules."],["年をとるにしたがって、記憶力が衰えてくる。","As one ages, one's memory declines."],["指示にしたがって、作業を進めた。","I proceeded with the work according to the instructions."]],"draft"],["ni-sotte-along","Noun + に沿って","沿着……；按照……","along / in accordance with","Noun + に沿って (adverbially). Noun + に沿った + noun (attributively).",[["川に沿って歩きました。","I walked along the river."],["会社の方針に沿って行動してください。","Please act in accordance with company policy."],["計画に沿ってプロジェクトを進めた。","I proceeded with the project according to plan."]],"draft"],["mono-no-although","Plain form + ものの","虽然……但是……（正式）","although / even though (formal)","V plain / i-adj + ものの; na-adj + な + ものの; noun + である + ものの.",[["宿題を始めたものの、なかなか進まない。","Although I started my homework, it's not progressing much."],["買ったものの、一度も使っていない。","Although I bought it, I've never used it."],["約束したものの、守れなかった。","Although I promised, I couldn't keep my word."]],"draft"],["ka-no-you-ni","Plain form + かのように","好像……一样；仿佛……","as if / as though","V plain / i-adj + かのように; na-adj + (な / である) + かのように; noun + (である / の) + かのように.",[["彼はまるで何も知らないかのように話した。","He talked as if he knew nothing at all."],["夢を見ているかのような気分だ。","I feel as if I'm dreaming."],["時間が止まったかのように静かだ。","It's quiet as if time had stopped."]],"draft"],["mono-nara-if-possible","V potential form + ものなら","如果可能……的话","if (it were) possible / if I could","V potential form + ものなら. Sometimes V dict + ものなら.",[["昔に戻れるものなら、戻りたい。","If I could go back to the past, I would."],["会えるものなら、もう一度会いたい。","If I could meet (him) again, I would want to."],["飛べるものなら、今すぐ日本へ行きたい。","If I could fly, I'd want to go to Japan right now."]],"draft"],["wo-motoni-based-on","Noun + をもとに","以……为基础；根据……","based on / on the basis of","Noun + をもとに (adverbial) / をもとにして (emphatic adverbial) / をもとにした + noun (attributive).",[["この小説は実話をもとに書かれた。","This novel was written based on a true story."],["データをもとに分析する。","I'll analyze based on the data."],["経験をもとにアドバイスします。","I'll give advice based on experience."]],"draft"],["ue-ni-in-addition","Plain form + 上に","不仅……而且……","in addition to / on top of (that)","V plain / i-adj + 上に; na-adj + な / である + 上に; noun + である + 上に.",[["この部屋は広い上に、明るい。","This room is spacious and also bright."],["頭が痛い上に、熱もある。","On top of having a headache, I also have a fever."],["彼は頭がいい上に、親切だ。","He is smart and on top of that, kind."]],"draft"],["ue-wa-now","V plain + 上は","既然……就……（正式）","now that / since (formal, implies commitment)","V plain (non-past or past) + 上は.",[["約束した上は、必ず守る。","Now that I've promised, I'll definitely keep my word."],["引き受けた上は、全力を尽くす。","Now that I've taken it on, I'll give it my all."],["日本に来た上は、日本語を話せるようになりたい。","Now that I've come to Japan, I want to be able to speak Japanese."]],"draft"],["ijou-since","Plain form + 以上(は)","既然……就……；只要……","since / now that / as long as","V plain / i-adj + 以上(は); na-adj + である + 以上(は); noun + である + 以上(は).",[["約束した以上、守らなければならない。","Since I promised, I have to keep it."],["引き受けた以上は、最後までやる。","Now that I've taken it on, I'll see it through."],["学生である以上、勉強が本分だ。","As long as one is a student, studying is one's duty."]],"draft"],["shikamo-moreover","しかも (sentence-initial)","而且……；更进一步","moreover / what's more / on top of that","[Previous sentence]. しかも [additional statement].",[["彼は頭がいい。しかも、性格も素晴らしい。","He's smart. Moreover, his personality is wonderful."],["この商品は安い。しかも、品質もいい。","This product is cheap. What's more, the quality is good."],["雨が降っている。しかも、風も強い。","It's raining. On top of that, the wind is strong."]],"draft"],["bakari-no","Verb ます-stem / plain form + ばかりの / ばかりだ","不断地……（单向变化）","nothing but / only one way (to decline / increase)","V dict-form + ばかりだ; attributive V dict + ばかりの + noun.",[["物価は上がるばかりだ。","Prices keep only going up."],["状況は悪くなるばかりだった。","The situation kept only getting worse."],["人口は減るばかりだ。","The population keeps only decreasing."]],"draft"],["osore-ga-aru","V plain / noun + の + 恐れがある","有……风险；恐怕会……（负面）","risk of / fear that (may happen)","V plain (non-past) + 恐れがある; noun + の + 恐れがある. Attributive: 〜恐れのある + noun.",[["明日は大雨の恐れがあります。","There's a risk of heavy rain tomorrow."],["この薬には副作用の恐れがある。","This medicine has a risk of side effects."],["地震が発生する恐れがある。","There's a risk of an earthquake occurring."]],"draft"],["zaru-wo-enai","V negative stem + ざるを得ない","不得不……；别无选择","cannot help but / have no choice but to","V ない-stem + ざるを得ない. Irregular: する → せざるを得ない.",[["彼の意見に賛成せざるを得ない。","I cannot help but agree with his opinion."],["そう結論づけざるを得ない。","One cannot help but conclude so."],["事実を認めざるを得ない。","I have no choice but to acknowledge the facts."]],"draft"],["ka-to-omou-to","V-た form + かと思うと / かと思ったら","刚一……就……（突然变化）","no sooner had / just when (unexpected change)","V-た + かと思うと / かと思ったら.",[["泣いたかと思うと、すぐ笑い出した。","No sooner had she cried than she started laughing."],["晴れたかと思うと、雨が降り出した。","Just when it cleared up, it started raining."],["寝たかと思ったら、もう起きている。","Just when I thought he was asleep, he's already awake."]],"draft"],["hodo-dewa-nai","Plain form + ほどではない","还没有到……的程度","not to the extent of / not as much as","V plain / i-adj + ほどではない; na-adj + な + ほどではない; noun + の + ほどではない.",[["痛いけど、病院に行くほどではない。","It hurts, but not to the extent of going to the hospital."],["忙しいが、断るほどではない。","I'm busy, but not so much that I need to decline."],["難しいけど、不可能なほどではない。","It's difficult, but not to the extent of being impossible."]],"draft"]];
